import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compileFromFile } from 'json-schema-to-typescript';

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const schemaPath = resolve(projectRoot, 'schemas/kite-avro-table-template.schema.json');
const outputPath = resolve(projectRoot, 'src/lib/generated/kite-avro-table-template.ts');

const declarations = await compileFromFile(schemaPath, {
	bannerComment:
		'// Generated by scripts/generate-avro-table-template-types.mjs. Do not edit manually.\n',
	style: {
		bracketSpacing: false,
		printWidth: 100,
		semi: true,
		singleQuote: true,
		tabWidth: 2,
		trailingComma: 'none',
		useTabs: true
	}
});

await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, declarations);
console.log(`Generated ${outputPath.replace(`${projectRoot}/`, '')}.`);
